def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {
        "+": 1,
        "-": 1,
        "*": 2,
        "/": 2,
        "%": 2,
        "neg": 3,
        "^": 4,
    }

    def apply():
        op = operators.pop()
        if op == "neg":
            values.append(-values.pop())
            return

        right = values.pop()
        left = values.pop()

        if op == "+":
            values.append(left + right)
        elif op == "-":
            values.append(left - right)
        elif op == "*":
            values.append(left * right)
        elif op == "^":
            if right < 0:
                raise ValueError
            values.append(pow(left, right))
        else:
            if right == 0:
                raise ValueError
            quotient = abs(left) // abs(right)
            if (left < 0) != (right < 0):
                quotient = -quotient
            if op == "/":
                values.append(quotient)
            else:
                values.append(left - right * quotient)

    try:
        i = 0
        expecting_operand = True

        while i < len(expr):
            ch = expr[i]

            if ch == " ":
                i += 1
            elif "0" <= ch <= "9":
                value = 0
                while i < len(expr) and "0" <= expr[i] <= "9":
                    value = value * 10 + (ord(expr[i]) - ord("0"))
                    i += 1
                values.append(value)
                expecting_operand = False
            elif ch == "(":
                operators.append(ch)
                expecting_operand = True
                i += 1
            elif ch == ")":
                while operators[-1] != "(":
                    apply()
                operators.pop()
                expecting_operand = False
                i += 1
            elif ch == "-" and expecting_operand:
                operators.append("neg")
                i += 1
            else:
                while operators and operators[-1] != "(":
                    top = operators[-1]
                    if precedence[top] > precedence[ch] or (
                        precedence[top] == precedence[ch] and ch != "^"
                    ):
                        apply()
                    else:
                        break
                operators.append(ch)
                expecting_operand = True
                i += 1

        while operators:
            apply()
        return values[0]
    except ValueError:
        return "error"
